Item.method_code:
/*
    マルQページの検索ビューにある「室課／GroupマルQページ作成」ボタンイベントの初期化メソッド
    
        ・複数のマルQページの選択が可能
            －選択した全てのマルQページのステータスが[承認]である事
            －選択した全てのマルQページの区分が[Sec]又は[Gr]である事
*/


//Innovatorオブジェクト生成
var iomInv = aras.IomInnovator;

// 検索グリッドの選択行ステータスによる有効化判定
var selectedRowsCount = options.getState().grid.selectedRows.length;
var disableFlag = true;

// マルQページが選択されている時のみ活性化
if (selectedRowsCount != 0) {
// debugger;
    // 選択行のItemId取得
    var classes = [];
    for (var i = 0; i < selectedRowsCount; i++) {
        var selectedItemId = options.getState().grid.selectedRows[i];
        
        // 選択行のItem State取得
        var selectedItem = iomInv.newItem(options.itemTypeName, "get");
        selectedItem.setID(selectedItemId);
        selectedItem.setAttribute("select", "state,h4_class");
        selectedItem = selectedItem.apply();
    
        var selectedItemState = selectedItem.getProperty("state");
        var selectedItemClass = selectedItem.getProperty("h4_class");

        // 異なる区分が存在するか確認
        if (! classes.includes(selectedItemClass)) {
            classes.push(selectedItemClass);
            
            if (classes.length == 2) {
                return {disabled: true};
            }
        }

debugger;    
        //ステータスが承認かつ区分がSecかGrの場合活性
        if ((selectedItemState == "Approved" || selectedItemState == "ProvisionalApproved") && (selectedItemClass == "Gr" || selectedItemClass == "Sec")) {
            disableFlag = false;
        } else {
            disableFlag = true;
            break;
        }
    }
}

return {disabled: disableFlag};
